.add-card-form input {
  flex-grow: 1;
  padding: 6px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.add-card-form button {
  padding: 6px 12px;
  background-color: #0052cc;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.add-card-form button:hover {
  background-color: #0065ff;
}
