  );

  for (let i = 0; i < cards.rows.length; i++) {
    await db.query(
      'UPDATE cards SET position = $1 WHERE id = $2',
      [ (i + 1) * 1000, cards.rows[i].id ]
    );
  }

  // Broadcast the full updated board state or just the column
  // To keep it simple, we can broadcast a 'boardUpdated' event
  broadcast('boardUpdated', { columnId });
}

