  background-color: #f4f5f7;
  margin: 0;
  padding: 20px;
}

.board {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  overflow-x: auto;
  padding-bottom: 20px;
}

.column {
  background-color: #ebecf0;
  border-radius: 8px;
  width: 300px;
  min-width: 300px;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
}

.column-header {
  padding: 12px;
  font-weight: bold;
  font-size: 1.1em;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.card-list {
  padding: 8px;
  flex-grow: 1;
  overflow-y: auto;
  min-height: 50px;
}

.card {
  background-color: #fff;
